describe('Countdown Timer - Interval Updates', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should update countdown timer every second', () => {
    cy.get('[data-testid="timer-display"]').should('contain', '10');

    cy.wait(1000);
    cy.get('[data-testid="timer-display"]').should('contain', '9');

    cy.wait(1000);
    cy.get('[data-testid="timer-display"]').should('contain', '8');

    cy.wait(1000);
    cy.get('[data-testid="timer-display"]').should('contain', '7');
  });

  it('should countdown to zero and stop', () => {
    cy.get('[data-testid="timer-display"]').should('contain', '10');

    cy.wait(10000);
    cy.get('[data-testid="timer-display"]').should('contain', '0');

    cy.wait(1000);
    cy.get('[data-testid="timer-display"]').should('contain', '0');
  });

  it('should handle timer pause and resume', () => {
    cy.get('[data-testid="timer-display"]').should('contain', '10');

    cy.get('[data-testid="pause-button"]').click();
    cy.wait(1000);
    cy.get('[data-testid="timer-display"]').should('contain', '10');

    cy.get('[data-testid="resume-button"]').click();
    cy.wait(1000);
    cy.get('[data-testid="timer-display"]').should('contain', '9');
  });

  it('should reset timer to initial value', () => {
    cy.wait(3000);
    cy.get('[data-testid="timer-display"]').should('contain', '7');

    cy.get('[data-testid="reset-button"]').click();
    cy.get('[data-testid="timer-display"]').should('contain', '10');
  });

  it('should handle rapid interval updates without memory leaks', () => {
    cy.get('[data-testid="timer-display"]').should('exist');

    for (let i = 0; i < 5; i++) {
      cy.wait(1000);
      cy.get('[data-testid="timer-display"]').should('be.visible');
    }

    cy.get('[data-testid="timer-display"]').should('contain', '5');
  });
});
